/**
 * Burnaby Palace Restaurant — Complete Menu Seed with Images
 * Run: node_modules\.bin\tsx.cmd seed/seed-menu.ts
 */
import mongoose from 'mongoose';
import { readFileSync } from 'fs';
import { resolve } from 'path';

try {
  const env = readFileSync(resolve(process.cwd(), '.env.local'), 'utf-8');
  for (const line of env.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const idx = t.indexOf('=');
    if (idx === -1) continue;
    const k = t.slice(0, idx).trim();
    const v = t.slice(idx + 1).trim().replace(/^["']|["']$/g, '');
    if (!process.env[k]) process.env[k] = v;
  }
} catch { /* ignore */ }

const URI = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/burnaby-palace';

const CatSchema = new mongoose.Schema({ name: String, slug: { type: String, unique: true }, description: String, sortOrder: { type: Number, default: 0 }, isActive: { type: Boolean, default: true } }, { timestamps: true });
const ItemSchema = new mongoose.Schema({ name: String, slug: { type: String, unique: true }, description: String, price: Number, category: { type: mongoose.Schema.Types.ObjectId, ref: 'Category' }, image: String, isAvailable: { type: Boolean, default: true }, isFeatured: { type: Boolean, default: false }, sortOrder: { type: Number, default: 0 } }, { timestamps: true });

const Cat  = mongoose.models.Category || mongoose.model('Category', CatSchema);
const Item = mongoose.models.MenuItem  || mongoose.model('MenuItem',  ItemSchema);

