// ─── SEED RUNNER ──────────────────────────────────────────────────────────────
async function seed() {
  await mongoose.connect(URI);
  console.log('✅ Connected to MongoDB at', URI);

  await Cat.deleteMany({});
  await Item.deleteMany({});
  console.log('🗑️  Cleared existing data');

  const createdCats = await Cat.insertMany(CATS);
  const catMap: Record<string, mongoose.Types.ObjectId> = {};
  for (const c of createdCats) {
    const cc = c as unknown as { slug: string; _id: mongoose.Types.ObjectId };
    catMap[cc.slug] = cc._id;
  }
  console.log(`📂 Created ${createdCats.length} categories`);

  const docs = ITEMS.map(({ cat, img, featured, sort, ...rest }) => ({
    ...rest,
    category: catMap[cat],
    image: img || '',
    isFeatured: featured,
    sortOrder: sort,
    isAvailable: true,
  }));

  const created = await Item.insertMany(docs);
  console.log(`🍜 Created ${created.length} menu items`);

  console.log('\n── Category breakdown ──');
  for (const c of CATS) {
    const n = ITEMS.filter(i => i.cat === c.slug).length;
    console.log(`  ${c.name.padEnd(42)} ${n} items`);
  }

  await mongoose.disconnect();
  console.log('\n🎉 Database seeded successfully!');
}

seed().catch(err => { console.error('❌ Seed failed:', err.message); process.exit(1); });
